const items = $input.all();
const vistas = ['FRENTE', 'ESPALDA', 'INTERIOR / ETIQUETA'];

function buscarTexto(obj) {
  if (!obj || typeof obj !== 'object') return '';
  if (typeof obj.text === 'string' && obj.text.trim()) return obj.text;
  for (const clave of Object.keys(obj)) {
    const encontrado = buscarTexto(obj[clave]);
    if (encontrado) return encontrado;
  }
  return '';
}

const analisis = vistas.map((vista, i) => ({
  vista,
  analisis: (items[i] ? buscarTexto(items[i].json) : '') ||
    'VISTA NO PROPORCIONADA: la clienta no subió esta foto. No inventes detalles de esta vista.'
}));

return [{ json: { analisis_completo: analisis } }];

function buscarTexto(obj) {
  if (!obj || typeof obj !== 'object') return '';
  if (typeof obj.text === 'string' && obj.text.includes('===OPCION_1===')) return obj.text;
  for (const clave of Object.keys(obj)) {
    const encontrado = buscarTexto(obj[clave]);
    if (encontrado) return encontrado;
  }
  return '';
}

const texto = buscarTexto($json);
const partes = texto.split(/===OPCION_\d===/).map(p => p.trim()).filter(Boolean);

if (partes.length < 3) {
  throw new Error('No se encontraron las 3 opciones. Inicio del texto: ' + JSON.stringify($json).slice(0, 400));
}

return {
  json: {
    texto_baja: partes[0],
    texto_media: partes[1],
    texto_alta: partes[2]
  },
  binary: $('Formulario').first().binary
};

const items = $input.all();
const form = $('Formulario').first().json;
const cod1 = $('Code in JavaScript1').first().json;

const nombreClienta = form['Nombre'] || '';   // <- ajustá al nombre real del campo
const niveles = ['Intervención sutil', 'Intervención visible', 'Reconstrucción profunda'];
const claves = ['baja', 'media', 'alta'];

function limpiar(texto) {
  const sinPrompt = texto.split(/\n\s*\**\s*10\.\s*\**\s*PROMPT[_ ]IMAGEN/i)[0];
  return sinPrompt
    .replace(/===OPCION_\d===/g, '')
    .trim()
    .split('\n')
    .filter(l => l.trim())
    .filter(l => !/(precio|costo|valor|presupuesto|\$|USD|ARS)/i.test(l))
    .map(l => l.replace(/^\s*(\d+)\.\s*([^:]+):/, '<strong>$2:</strong>'))
    .map(l => `<p style="margin:0 0 8px 0;">${l}</p>`)
    .join('');
}

const fmt = n => '$' + Number(n).toLocaleString('es-AR');

let bloques = '';
const binary = {};

items.forEach((item, i) => {
  const texto = cod1['texto_' + claves[i]] || '';

  bloques += `
    <div style="border-top:1px solid #d9d4cc; padding:24px 0;">
      <p style="margin:0; font-size:12px; letter-spacing:2px; text-transform:uppercase; color:#8a8378;">
        Opción ${i + 1} · ${niveles[i]}
      </p>
      <div style="margin-top:12px; font-size:15px; line-height:1.6; color:#2b2926;">
        ${limpiar(texto)}
      </div>

      <p style="margin:12px 0 0 0; font-size:13px; color:#8a8378;">
        Mirá la imagen adjunta <em>propuesta_${i + 1}.png</em>.
      </p>
    </div>`;
  if (item.binary && item.binary.data) {
    binary[`imagen_${i + 1}`] = { ...item.binary.data, fileName: `propuesta_${i + 1}.png` };
  }
});

const html = `
<div style="max-width:620px; margin:0 auto; font-family:Helvetica,Arial,sans-serif; color:#2b2926;">
  <h1 style="font-weight:400; letter-spacing:6px; font-size:28px; margin:0 0 4px 0;">GEN</h1>
  <p style="margin:0 0 24px 0; font-size:12px; color:#8a8378;">Moda circular · Reconstrucción y memoria</p>

  <p style="font-size:15px; line-height:1.6;">Hola${nombreClienta ? ' ' + nombreClienta : ''},</p>
  <p style="font-size:15px; line-height:1.6;">
    Gracias por confiarnos tu prenda. La miramos con atención y 
     pensamos tres caminos posibles para reconstruirla. Van de un cambio sutil a una transformación profunda.
    Las imágenes son una referencia visual de cada idea, no un resultado exacto: el diseño final se ajusta
    a la tela y al estado real de tu prenda.
  </p>

  ${bloques}

  <div style="border-top:1px solid #d9d4cc; padding-top:24px; font-size:15px; line-height:1.6;">
    <p>¿Cuál te llamó más la atención? Respondé este mail contándonos tu elección, o si querés mezclar
    elementos de distintas propuestas, y coordinamos los próximos pasos.</p>
        <p>El valor de cada propuesta te lo enviamos por separado, una vez que elijas tu opción.</p>
    <p style="margin-top:20px;">Un abrazo,<br><strong>Equipo Gen</strong><br>
    <span style="font-size:13px; color:#8a8378;">Instagram: @somosigriega</span></p>
  </div>
</div>`;

return [{
  json: {
    to: form['Email'],            // <- ajustá al nombre real del campo
    subject: 'Tus 3 propuestas para reconstruir tu prenda | Gen',
    html
  },
  binary
}];
